// Web worker entry: OpenNext's worker plus one addition. Next.js route
// handlers can't complete a WebSocket upgrade, so upgrade requests for the
// realtime socket go straight to the API worker (which owns the Durable
// Object). Everything else is the stock OpenNext worker.
//
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import openNext from '../../.open-next/worker.js'

interface Env {
  API: { fetch(request: Request): Promise<Response> }
}

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url)
    if (url.pathname === '/api/realtime/socket' && request.headers.get('Upgrade') === 'websocket') {
      return env.API.fetch(request)
    }
    return openNext.fetch(request, env, ctx)
  },
}

// OpenNext's Durable Object classes (unused by this app's config, re-exported
// so the worker keeps working if ISR/tag caching is enabled later).
// @ts-expect-error: generated
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from '../../.open-next/worker.js'
